	@Test
	public void snapshotCapturedBetweenStagingAndPublicationRetainsItsBoundary() {
		SailSource source = store.getExplicitSailSource();
		try (SailSink staged = source.sink(IsolationLevels.READ_COMMITTED);
				SailSourceBranch reader = new SailSourceBranch(source)) {
			staged.approve(FIRST);
			int captured = count(reader, IsolationLevels.SNAPSHOT, P);
			assertTrue(captured == 0 || captured == 1, "The source view contains at most the staged row");
			staged.flush();
			assertEquals(captured, count(reader, IsolationLevels.SERIALIZABLE, P),
					"Publication must preserve the actual view returned at acquisition");
			write(reader, statement("between-staging-marker", Q));
			if (captured == 0) {
				SailConflictException conflict = assertThrows(SailConflictException.class, reader::prepare);
				assertEquals("Observed State has Changed", conflict.getMessage());
			} else {
				reader.flush();
			}
		}
		assertTrue(contains(source, FIRST));
	}

	@Test
	public void lateSnapshotPreservesRemovalClearAndQueryDeletion() {
		SailSource source = store.getExplicitSailSource();
		for (int operation = 0; operation < 3; operation++) {
			Statement existing = statement("late-removal:" + operation, P);
			write(source, existing);
			try (SailSink staged = source.sink(IsolationLevels.READ_COMMITTED);
					SailSourceBranch reader = new SailSourceBranch(source)) {
				if (operation == 0) {
					staged.deprecate(existing);
				} else if (operation == 1) {
					staged.clear();
				} else if (staged.supportsDeprecateByQuery()) {
					assertTrue(staged.deprecateByQuery(existing.getSubject(), P, null, new Resource[0]));
				} else {
					staged.deprecate(existing);
				}
				assertTrue(contains(reader, IsolationLevels.SNAPSHOT, existing));
				staged.flush();
				assertTrue(contains(reader, IsolationLevels.SERIALIZABLE, existing));
				write(reader, statement("late-removal-marker:" + operation, Q));
				SailConflictException conflict = assertThrows(SailConflictException.class, reader::prepare);
				assertEquals("Observed State has Changed", conflict.getMessage());
			}
			assertFalse(contains(source, existing));
		}
	}

