	@Test
	public void lowerSourceSinkSupportsSequentialThreadHandoff() throws Exception {
		SailSource source = store.getExplicitSailSource();
		for (IsolationLevel level : new IsolationLevel[] { IsolationLevels.NONE, IsolationLevels.READ_COMMITTED,
				IsolationLevels.SNAPSHOT_READ, IsolationLevels.SNAPSHOT }) {
			Statement written = statement("thread-handoff:" + level, P);
			SailSink sink = source.sink(level);
			try (var first = Executors.newSingleThreadExecutor(); var second = Executors.newSingleThreadExecutor()) {
				first.submit(() -> {
					sink.prepare();
					sink.approve(written);
				}).get(5, TimeUnit.SECONDS);
				try {
					second.submit(sink::flush).get(5, TimeUnit.SECONDS);
				} finally {
					first.submit(sink::close).get(5, TimeUnit.SECONDS);
				}
			}
			assertTrue(contains(source, written),
					"Lower-level operations retain sequential cross-thread use: " + level);
		}
	}

