	@Test
	public void snapshotUpgradeUsesCapturedBoundaryForMatchingAndNonmatchingWrites() {
		SailSource explicit = store.getExplicitSailSource();
		for (boolean matching : new boolean[] { true, false }) {
			IRI observed = VF.createIRI("urn:raw-observation:range:" + matching);
			Statement arriving = statement("arriving:" + matching, matching ? observed : Q);
			Statement marker = statement("marker:" + matching, Q);
			try (SailSourceBranch branch = new SailSourceBranch(explicit)) {
				assertEquals(0, count(branch, IsolationLevels.SNAPSHOT, observed));
				write(explicit, arriving);
				assertEquals(0, count(branch, IsolationLevels.SERIALIZABLE, observed));
				write(branch, marker);
				if (matching) {
					SailConflictException conflict = assertThrows(SailConflictException.class, branch::prepare);
					assertEquals("Observed State has Changed", conflict.getMessage());
				} else {
					branch.flush();
					assertEquals(0, count(branch, IsolationLevels.SNAPSHOT, observed));
					assertTrue(contains(explicit, marker));
				}
			}
			assertTrue(contains(explicit, arriving));
		}
	}

