	@Test
	public void forcedPublicationAndReuseKeepExistingCursorAndOwnOverlays() {
		SailSource explicit = store.getExplicitSailSource();
		write(explicit, FIRST);
		write(explicit, SECOND);
		Statement ownFirst = statement("own-first", Q);
		Statement ownSecond = statement("own-second", Q);
		try (SailSourceBranch branch = new SailSourceBranch(explicit);
				SailDataset view = branch.dataset(IsolationLevels.SNAPSHOT);
				var cursor = view.getStatements((Resource) null, P, null);
				SailSink reused = branch.sink(IsolationLevels.READ_COMMITTED)) {
			Set<Statement> seen = new HashSet<>();
			assertTrue(cursor.hasNext());
			seen.add(cursor.next());
			reused.approve(ownFirst);
			reused.flush();
			branch.flush();
			while (cursor.hasNext()) {
				seen.add(cursor.next());
			}
			assertEquals(Set.of(FIRST, SECOND), seen);
			assertEquals(1, count(branch, IsolationLevels.SNAPSHOT, Q));
			reused.approve(ownSecond);
			reused.flush();
			branch.flush();
			branch.flush();
			assertEquals(2, count(branch, IsolationLevels.SNAPSHOT, Q));
			try (SailSink writer = explicit.sink(IsolationLevels.READ_COMMITTED)) {
				writer.deprecate(FIRST);
				writer.flush();
			}
			assertTrue(contains(branch, IsolationLevels.SNAPSHOT, FIRST));
			assertEquals(2, count(branch, IsolationLevels.SNAPSHOT, Q));
		}
		assertFalse(contains(explicit, FIRST));
		assertTrue(contains(explicit, ownFirst));
		assertTrue(contains(explicit, ownSecond));
	}

	@Test
	public void explicitPublicationPreservesAnInferredCursorAndView() {
		SailSource inferred = store.getInferredSailSource();
		write(inferred, FIRST);
		write(inferred, SECOND);
		try (SnapshotReadContext snapshot = capable(inferred).acquireSnapshot(IsolationLevels.SNAPSHOT);
				var cursor = snapshot.dataset().getStatements((Resource) null, P, null)) {
			Set<Statement> seen = new HashSet<>();
			assertTrue(cursor.hasNext());
			seen.add(cursor.next());
			write(store.getExplicitSailSource(), statement("explicit-sibling", Q));
			while (cursor.hasNext()) {
				seen.add(cursor.next());
			}
			assertEquals(Set.of(FIRST, SECOND), seen);
			assertEquals(2, count(snapshot.dataset(), P));
		}
	}

	@Test
	public void namespacePublicationPreservesCapturedOtherParticipant() {
		SailSource explicit = store.getExplicitSailSource();
		try (SailSink writer = explicit.sink(IsolationLevels.READ_COMMITTED)) {
			writer.setNamespace("captured", "urn:namespace:old");
			writer.flush();
		}
		try (SnapshotReadContext snapshot = capable(store.getInferredSailSource())
				.acquireSnapshot(IsolationLevels.SNAPSHOT)) {
			assertEquals("urn:namespace:old", snapshot.dataset().getNamespace("captured"));
			try (SailSink writer = explicit.sink(IsolationLevels.READ_COMMITTED)) {
				writer.setNamespace("captured", "urn:namespace:new");
				writer.flush();
			}
			assertEquals("urn:namespace:old", snapshot.dataset().getNamespace("captured"));
		}
		try (SailDataset current = explicit.dataset(IsolationLevels.READ_COMMITTED)) {
			assertEquals("urn:namespace:new", current.getNamespace("captured"));
		}
	}

