	@Test
	public void adoptedOwnPromotionPreservesUnionViewWithoutSelfConflict() {
		SailSource inferred = store.getInferredSailSource();
		SailSource explicit = store.getExplicitSailSource();
		write(inferred, FIRST);
		try (SailSourceBranch parent = new SailSourceBranch(new UnionSailSource(explicit, inferred));
				SailSource child = parent.fork()) {
			assertTrue(contains(parent, IsolationLevels.SERIALIZABLE, FIRST));
			write(child, FIRST);
			child.flush();
			parent.flush();
			assertEquals(1, count(parent, IsolationLevels.SNAPSHOT, P));
			assertTrue(contains(parent, IsolationLevels.SNAPSHOT, FIRST));
			parent.flush();
			assertEquals(1, count(parent, IsolationLevels.SNAPSHOT, P));
		}
		assertTrue(contains(explicit, FIRST));
		assertFalse(contains(inferred, FIRST));
	}

